<?php
session_start();include 'config.php';if(!isset($_SESSION['doctor_id'])){header('Location:index.php');exit;}$doctor_id=(int)$_SESSION['doctor_id'];$s=$conn->prepare('SELECT * FROM doctors WHERE id=?');$s->bind_param('i',$doctor_id);$s->execute();$doctor=$s->get_result()->fetch_assoc();if(!$doctor){session_destroy();header('Location:index.php');exit;}$name=$doctor['full_name'];
$filterDate=trim($_GET['date']??'');$sql="SELECT a.*,u.name patient_name,u.email patient_email,u.phone patient_phone FROM appointments a LEFT JOIN users u ON u.id=a.user_id WHERE a.doctor_name=?";$types='s';$params=[$name];if($filterDate!==''){$sql.=' AND a.appointment_date=?';$types.='s';$params[]=$filterDate;}$sql.=' ORDER BY a.appointment_date DESC,a.appointment_time ASC';$st=$conn->prepare($sql);$st->bind_param($types,...$params);$st->execute();$res=$st->get_result();$rows=[];$pending=$confirmed=$treated=0;while($r=$res->fetch_assoc()){$rows[]=$r;$status=$r['status']??'Pending';if($status==='Pending')$pending++;if($status==='Confirmed')$confirmed++;if($status==='Completed')$treated++;}$patientCount=count(array_unique(array_filter(array_column($rows,'user_id'))));
$all=$conn->prepare("SELECT DISTINCT u.id,u.name,u.email,u.phone FROM appointments a JOIN users u ON u.id=a.user_id WHERE a.doctor_name=? ORDER BY u.name");$all->bind_param('s',$name);$all->execute();$patients=$all->get_result()->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Doctor Dashboard - MedEase</title><link rel="stylesheet" href="style.css"><style>
body{margin:0;background:#f4f7fb;font-family:'Segoe UI',Arial,sans-serif;color:#182033}.dash-nav{background:#fff;padding:14px 5%;display:flex;justify-content:space-between;align-items:center;box-shadow:0 2px 12px #0001;position:sticky;top:0;z-index:20}.brand{display:flex;align-items:center;gap:10px;font-weight:800;color:#4f46e5}.brand img{width:42px;height:42px;border-radius:10px}.btn{background:#4f46e5;color:#fff;padding:10px 16px;border-radius:9px;text-decoration:none;border:0;cursor:pointer;font-weight:600}.dashboard{display:grid;grid-template-columns:340px 1fr;gap:24px;padding:28px 5%}.card{background:#fff;border-radius:18px;padding:22px;box-shadow:0 8px 25px #1e293b12;margin-bottom:22px}.profile-head{text-align:center}.avatar-img{width:120px;height:120px;border-radius:50%;object-fit:cover;border:5px solid #eef2ff}.avatar{font-size:80px}.muted{color:#64748b}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat{background:#eef2ff;padding:18px;border-radius:14px}.stat b{font-size:28px;display:block}.field{margin:10px 0}.field input,.field textarea,.field select{width:100%;box-sizing:border-box;padding:11px;border:1px solid #cbd5e1;border-radius:9px}.actions{display:flex;gap:7px;flex-wrap:wrap}.green{background:#059669}.red{background:#dc2626}.gray{background:#64748b}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #e5e7eb}th{background:#eef2ff}.appointments{overflow:auto}.switch-row{display:flex;align-items:center;gap:14px}.switch{position:relative;width:58px;height:30px}.switch input{opacity:0;width:0;height:0}.slider{position:absolute;inset:0;background:#cbd5e1;border-radius:30px;cursor:pointer}.slider:before{content:'';position:absolute;width:24px;height:24px;left:3px;top:3px;background:#fff;border-radius:50%;transition:.2s}.switch input:checked+.slider{background:#16a34a}.switch input:checked+.slider:before{transform:translateX(28px)}@media(max-width:900px){.dashboard{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}}@media(max-width:550px){.stats{grid-template-columns:1fr}}
</style></head><body><nav class="dash-nav"><div class="brand"><img src="logo.jpeg">MedEase · Doctor Dashboard</div><div class="actions"><a class="btn" href="index.php">Home</a><a class="btn red" href="logout.php">Logout</a></div></nav><div class="dashboard"><aside><div class="card profile-head"><?php if(!empty($doctor['profile_photo'])):?><img class="avatar-img" src="<?=htmlspecialchars($doctor['profile_photo'])?>" alt="Doctor photo"><?php else:?><div class="avatar"><?=$doctor['gender']==='Female'?'👩‍⚕️':'👨‍⚕️'?></div><?php endif;?><h2><?=htmlspecialchars($doctor['full_name'])?></h2><p class="muted"><?=htmlspecialchars($doctor['specialization'])?></p><p><b>Reg. No:</b> <?=htmlspecialchars($doctor['medical_registration_no'])?></p><p><b>Experience:</b> <?=htmlspecialchars($doctor['experience'])?> years</p><p><b>Hospital:</b> <?=htmlspecialchars($doctor['hospital'])?></p><p><b>Email:</b> <?=htmlspecialchars($doctor['email'])?></p><p><b>Phone:</b> <?=htmlspecialchars($doctor['phone'])?></p><a class="btn" href="edit_doctor.php">Edit Profile</a></div></aside><main><div class="stats"><div class="stat"><b><?=$pending?></b>Pending</div><div class="stat"><b><?=$confirmed?></b>Confirmed</div><div class="stat"><b><?=$treated?></b>Treated<?=$filterDate?' on selected date':''?></div><div class="stat"><b><?=$patientCount?></b>Patients in view</div></div>
<div class="card"><h3>Availability</h3><form action="update_availability.php" method="post"><div class="switch-row"><label class="switch"><input id="availabilityToggle" type="checkbox" <?=$doctor['availability']==='Yes'?'checked':''?> onchange="document.getElementById('availabilityValue').value=this.checked?'Yes':'No';this.form.submit()"><span class="slider"></span></label><input type="hidden" id="availabilityValue" name="availability" value="<?=htmlspecialchars($doctor['availability'])?>"><b><?=$doctor['availability']==='Yes'?'Available: Yes':'Available: No'?></b></div></form></div>
<div class="card"><h3>Filter treatment by date</h3><form method="get" class="actions"><input style="padding:10px;border:1px solid #cbd5e1;border-radius:9px" type="date" name="date" value="<?=htmlspecialchars($filterDate)?>"><button class="btn">Apply Filter</button><?php if($filterDate):?><a class="btn gray" href="doctor_dashboard.php">Clear</a><?php endif;?></form><?php if($filterDate):?><p class="muted">Completed treatments on <?=htmlspecialchars($filterDate)?>: <b><?=$treated?></b></p><?php endif;?></div>
<div class="card appointments"><h3>Appointment List</h3><?php if($rows):?><table><tr><th>Patient</th><th>Date & Time</th><th>Reason</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $a):?><tr><td><?=htmlspecialchars($a['patient_name']??'Patient')?><small class="muted"><br><?=htmlspecialchars($a['patient_phone']??'')?></small></td><td><?=htmlspecialchars($a['appointment_date'])?><br><?=htmlspecialchars($a['appointment_time'])?></td><td><?=htmlspecialchars($a['reason'])?></td><td><?=htmlspecialchars($a['status']??'Pending')?></td><td><div class="actions"><a class="btn green" href="update_appointment_status.php?id=<?=$a['id']?>&status=Confirmed">Confirm</a><a class="btn red" href="update_appointment_status.php?id=<?=$a['id']?>&status=Rejected">Reject</a><a class="btn gray" href="update_appointment_status.php?id=<?=$a['id']?>&status=Completed">Complete</a></div></td></tr><?php endforeach;?></table><?php else:?><p class="muted">No appointments found for this view.</p><?php endif;?></div>
<div class="card" id="recommendations"><h3>Patient Recommendation</h3><form action="save_recommendation.php" method="post"><div class="field"><label>Select connected patient</label><select name="user_id" required><option value="">Choose patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?> · <?=htmlspecialchars($p['phone'])?></option><?php endforeach;?></select></div><div class="field"><textarea name="recommendation" rows="5" placeholder="Write recommendation for the selected patient" required></textarea></div><button class="btn">Save Recommendation</button></form></div>
<div class="card"><h3>MedEase Assistant</h3><div id="chat" style="height:210px;overflow:auto;background:#f8fafc;padding:12px;border-radius:10px;margin-bottom:10px"><div style="padding:8px;background:#e2e8f0;border-radius:9px">Ask me about your appointments, patients, availability, or dashboard.</div></div><div class="actions"><input id="chatInput" style="flex:1;padding:11px;border:1px solid #cbd5e1;border-radius:9px" placeholder="Type a question..."><button class="btn" onclick="askBot()">Send</button></div></div></main></div><script>async function askBot(){const i=document.getElementById('chatInput'),c=document.getElementById('chat'),q=i.value.trim();if(!q)return;c.innerHTML+=`<div style="padding:8px;margin:7px 0;background:#e0e7ff;border-radius:9px">${q.replace(/[<>]/g,'')}</div>`;i.value='';const r=await fetch('doctor_chatbot.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'message='+encodeURIComponent(q)});c.innerHTML+=`<div style="padding:8px;margin:7px 0;background:#e2e8f0;border-radius:9px">${await r.text()}</div>`;c.scrollTop=c.scrollHeight}</script></body></html>
